(7153850, 1097284, 108069, '<td valign="top">Very nice. Well composed and the colors are somehow soothing. Nice scene.</td>', 'Very nice. Well composed and the colors are somehow soothing. Nice scene.', '2014-01-07 16:43:11.000000', NULL, 1),
(7153852, 1097371, 108069, '<td valign="top">Love the dab of light on the barn. Lovely color gradient to the sky. Great time to shoot this. Nicely done.</td>', 'Love the dab of light on the barn. Lovely color gradient to the sky. Great time to shoot this. Nicely done.', '2014-01-07 16:43:50.000000', NULL, 1),
(7153901, 1097347, 108069, '<td valign="top">Really nice scene. It''s extremely crisp, which I suppose does represent the cold well, but (to me!) the texture of the water, rocks and ice add a bit of agitation to a scene I''d hope to be more tranquil and soothing. Probably just my insane interest in long, peaceful walks on the beach shining through here. Nicely framed and composed.</td>', 'Really nice scene. It''s extremely crisp, which I suppose does represent the cold well, but (to me!) the texture of the water, rocks and ice add a bit of agitation to a scene I''d hope to be more tranquil and soothing. Probably just my insane interest in long, peaceful walks on the beach shining through here. Nicely framed and composed.', '2014-01-07 18:40:03.000000', NULL, 1),
(7153902, 1096663, 108069, '<td valign="top">Great mood. Nice amount of murk.</td>', 'Great mood. Nice amount of murk.', '2014-01-07 18:40:32.000000', NULL, 1),
(7153903, 1097293, 108069, '<td valign="top">Pretty cool puzzle. Like the tones and grain a lot. Contrasted shapes within shapes. Very nice.</td>', 'Pretty cool puzzle. Like the tones and grain a lot. Contrasted shapes within shapes. Very nice.', '2014-01-07 18:41:29.000000', NULL, 1),
(7153904, 1097406, 108069, '<td valign="top">Great use of light. Her expression is great as well, as if she''s witnessing the transformation herself. Lighting and tones give it a really genuine and natural feel. Well done.</td>', 'Great use of light. Her expression is great as well, as if she''s witnessing the transformation herself. Lighting and tones give it a really genuine and natural feel. Well done.', '2014-01-07 18:45:03.000000', NULL, 1),
(7153905, 1097234, 108069, '<td valign="top">Excellent flash of colors among the severe contrast. Photo has an iconic quality to it. Very nice.</td>', 'Excellent flash of colors among the severe contrast. Photo has an iconic quality to it. Very nice.', '2014-01-07 18:46:36.000000', NULL, 1),
(7153906, 1097417, 108069, '<td valign="top">Great color to this image. Nicely lit. Good one.</td>', 'Great color to this image. Nicely lit. Good one.', '2014-01-07 18:48:08.000000', NULL, 1),
